def search_repositories(query, visibility=None, owner_login=None, is_fork=None, status=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "search_repositories"

    # Minimal observable dynamics store (create on demand)
    req_file = "gh_request_log.json"
    usage_file = "gh_usage_counters.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, message=None, used_credential_id=None):
        try:
            reqs = _load(req_file)
            counters = _load(usage_file)
            if not isinstance(reqs, list): reqs = []
            if not isinstance(counters, dict): counters = {}
            counters.setdefault("total_calls", 0)
            counters.setdefault("by_endpoint", {})
            counters.setdefault("daily", {})  # YYYY-MM-DD -> count
            counters.setdefault("last_call_at", None)

            ts = _now()
            reqs.append({
                "id": f"ghrl_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential_id": used_credential_id,
                "status": status_code,
                "message": message,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": ts
            })
            counters["total_calls"] += 1
            counters["by_endpoint"][endpoint] = counters["by_endpoint"].get(endpoint, 0) + 1
            day = ts[:10]
            counters["daily"][day] = counters["daily"].get(day, 0) + 1
            counters["last_call_at"] = ts

            _save(req_file, reqs)
            _save(usage_file, counters)
        except Exception:
            # Do not raise; logging failures should not break endpoint
            return

    def _rate_limit_check():
        # Simple local limit: 300 calls per rolling minute across all endpoints
        try:
            reqs = _load(req_file)
            if not isinstance(reqs, list): return None
            cutoff = time.time() - 60
            cnt = 0
            for r in reqs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str) or len(ts) < 20:
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.timestamp() >= cutoff:
                        cnt += 1
                except Exception:
                    continue
            if cnt >= 300:
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=60)
            return None
        except Exception:
            return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        e = _err("VALIDATION_ERROR", "query must be a non-empty string.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if visibility is not None and visibility not in ("public", "private", "internal"):
        e = _err("VALIDATION_ERROR", "visibility must be one of: public, private, internal.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if owner_login is not None and (not isinstance(owner_login, str) or owner_login == ""):
        e = _err("VALIDATION_ERROR", "owner_login must be a non-empty string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if is_fork is not None and not isinstance(is_fork, bool):
        e = _err("VALIDATION_ERROR", "is_fork must be a boolean when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if status is not None and status not in ("active", "archived", "deleted"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if sort is None:
        sort = "updated_at"
    if sort not in ("updated_at", "created_at", "name"):
        e = _err("VALIDATION_ERROR", "sort must be one of: updated_at, created_at, name.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    def _decode_cursor(c):
        if not c:
            return 0
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    offset = _decode_cursor(cursor)
    if offset is None:
        e = _err("VALIDATION_ERROR", "Invalid cursor.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    repos = _load("gh_repositories.json")
    if not isinstance(repos, list):
        repos = []

    q = query.strip().lower()
    terms = [t for t in re.split(r"\s+", q) if t]

    def _matches_fulltext(r):
        hay = " ".join([
            str(r.get("full_name") or ""),
            str(r.get("description") or ""),
            str(r.get("owner_login") or ""),
            str(r.get("name") or "")
        ]).lower()
        # AND semantics across terms
        for t in terms:
            if t not in hay:
                return False
        return True

    filtered = []
    for r in repos:
        if not isinstance(r, dict):
            continue
        # Business rule: exclude deleted from search results
        if r.get("status") == "deleted":
            continue
        if status is not None and r.get("status") != status:
            continue
        if visibility is not None and r.get("visibility") != visibility:
            continue
        if owner_login is not None and r.get("owner_login") != owner_login:
            continue
        if is_fork is not None and r.get("is_fork") is not is_fork:
            continue
        if _matches_fulltext(r):
            filtered.append(r)

    total = len(filtered)

    def _sort_key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at"):
            # ISO string sort is okay if standardized; handle None
            return v or ""
        return (v or "").lower()

    reverse = (order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "repositories": page,
        "page": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("OK")
    return resp

def search_code(query, repository_id=None, owner_login=None, repository_name=None, path_prefix=None, branch_name=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "search_code"
    req_file = "gh_request_log.json"
    usage_file = "gh_usage_counters.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, message=None, used_credential_id=None):
        try:
            reqs = _load(req_file)
            counters = _load(usage_file)
            if not isinstance(reqs, list): reqs = []
            if not isinstance(counters, dict): counters = {}
            counters.setdefault("total_calls", 0)
            counters.setdefault("by_endpoint", {})
            counters.setdefault("daily", {})
            counters.setdefault("last_call_at", None)

            ts = _now()
            reqs.append({
                "id": f"ghrl_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential_id": used_credential_id,
                "status": status_code,
                "message": message,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": ts
            })
            counters["total_calls"] += 1
            counters["by_endpoint"][endpoint] = counters["by_endpoint"].get(endpoint, 0) + 1
            day = ts[:10]
            counters["daily"][day] = counters["daily"].get(day, 0) + 1
            counters["last_call_at"] = ts

            _save(req_file, reqs)
            _save(usage_file, counters)
        except Exception:
            return

    def _rate_limit_check():
        try:
            reqs = _load(req_file)
            if not isinstance(reqs, list): return None
            cutoff = time.time() - 60
            cnt = 0
            for r in reqs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str) or len(ts) < 20:
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.timestamp() >= cutoff:
                        cnt += 1
                except Exception:
                    continue
            if cnt >= 300:
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=60)
            return None
        except Exception:
            return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        e = _err("VALIDATION_ERROR", "query must be a non-empty string.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    repo_pat = re.compile(r"^ghr_[0-9A-Z]{18,}$")
    if repository_id is not None:
        if not isinstance(repository_id, str) or not repo_pat.match(repository_id):
            e = _err("VALIDATION_ERROR", "repository_id is malformed.")
            _log("VALIDATION_ERROR", e["error"]["message"])
            return e
    if owner_login is not None and (not isinstance(owner_login, str) or owner_login == ""):
        e = _err("VALIDATION_ERROR", "owner_login must be a non-empty string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if repository_name is not None and (not isinstance(repository_name, str) or repository_name == ""):
        e = _err("VALIDATION_ERROR", "repository_name must be a non-empty string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if path_prefix is not None and not isinstance(path_prefix, str):
        e = _err("VALIDATION_ERROR", "path_prefix must be a string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if branch_name is not None and (not isinstance(branch_name, str) or branch_name == ""):
        e = _err("VALIDATION_ERROR", "branch_name must be a non-empty string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    def _decode_cursor(c):
        if not c:
            return 0
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    offset = _decode_cursor(cursor)
    if offset is None:
        e = _err("VALIDATION_ERROR", "Invalid cursor.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    repos = _load("gh_repositories.json")
    if not isinstance(repos, list): repos = []
    files = _load("gh_files.json")
    if not isinstance(files, list): files = []

    repo_by_id = {r.get("id"): r for r in repos if isinstance(r, dict) and isinstance(r.get("id"), str)}
    if repository_id is not None:
        repo = repo_by_id.get(repository_id)
        if not repo:
            e = _err("NOT_FOUND", "repository_id does not exist.")
            _log("NOT_FOUND", e["error"]["message"])
            return e

    q = query.strip().lower()
    terms = [t for t in re.split(r"\s+", q) if t]

    def _repo_ok(r):
        if not isinstance(r, dict):
            return False
        if r.get("status") == "deleted":
            return False
        if repository_id is not None and r.get("id") != repository_id:
            return False
        if owner_login is not None and r.get("owner_login") != owner_login:
            return False
        if repository_name is not None and r.get("name") != repository_name:
            return False
        return True

    allowed_repo_ids = set()
    for r in repos:
        if _repo_ok(r):
            allowed_repo_ids.add(r.get("id"))

    # Build matches from gh_files.path and optionally content_base64
    matches = []
    for f in files:
        if not isinstance(f, dict):
            continue
        rid = f.get("repository_id")
        if rid not in allowed_repo_ids:
            continue
        if branch_name is not None:
            if f.get("branch_name") != branch_name:
                continue
        if path_prefix is not None:
            p = f.get("path") or ""
            if not isinstance(p, str) or not p.startswith(path_prefix):
                continue

        path = f.get("path") or ""
        if not isinstance(path, str):
            continue

        hay = path.lower()
        content_b64 = f.get("content_base64")
        content_hit = False
        if isinstance(content_b64, str) and content_b64:
            # We can't reliably decode huge content; but attempt for search.
            try:
                decoded = base64.b64decode(content_b64.encode("utf-8"), validate=False)
                # Limit decode to avoid memory blowups
                if len(decoded) > 2_000_000:
                    decoded = decoded[:2_000_000]
                try:
                    txt = decoded.decode("utf-8", errors="ignore").lower()
                except Exception:
                    txt = ""
                hay2 = hay + "\n" + txt
            except Exception:
                hay2 = hay
        else:
            hay2 = hay  # path-level only when no content cached

        ok = True
        for t in terms:
            if t not in hay2:
                ok = False
                break
        if not ok:
            continue

        # Determine match kind
        if all(t in hay for t in terms):
            match_kind = "path"
        else:
            match_kind = "content" if isinstance(content_b64, str) and content_b64 else "path"

        r = repo_by_id.get(rid) or {}
        matches.append({
            "repository_id": rid,
            "repository_full_name": r.get("full_name"),
            "owner_login": r.get("owner_login"),
            "repository_name": r.get("name"),
            "path": path,
            "branch_name": f.get("branch_name"),
            "blob_sha": f.get("blob_sha"),
            "match_kind": match_kind,
            "file_id": f.get("id")
        })

    # Sort: stable deterministic by repo then path
    matches.sort(key=lambda m: ((m.get("repository_full_name") or ""), (m.get("path") or ""), (m.get("branch_name") or "")))

    total = len(matches)
    page = matches[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "matches": page,
        "page": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("OK")
    return resp

def search_users(query, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "search_users"
    req_file = "gh_request_log.json"
    usage_file = "gh_usage_counters.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, message=None, used_credential_id=None):
        try:
            reqs = _load(req_file)
            counters = _load(usage_file)
            if not isinstance(reqs, list): reqs = []
            if not isinstance(counters, dict): counters = {}
            counters.setdefault("total_calls", 0)
            counters.setdefault("by_endpoint", {})
            counters.setdefault("daily", {})
            counters.setdefault("last_call_at", None)

            ts = _now()
            reqs.append({
                "id": f"ghrl_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential_id": used_credential_id,
                "status": status_code,
                "message": message,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": ts
            })
            counters["total_calls"] += 1
            counters["by_endpoint"][endpoint] = counters["by_endpoint"].get(endpoint, 0) + 1
            day = ts[:10]
            counters["daily"][day] = counters["daily"].get(day, 0) + 1
            counters["last_call_at"] = ts

            _save(req_file, reqs)
            _save(usage_file, counters)
        except Exception:
            return

    def _rate_limit_check():
        # Search endpoints are more restrictive: 60/min.
        try:
            reqs = _load(req_file)
            if not isinstance(reqs, list): return None
            cutoff = time.time() - 60
            cnt = 0
            for r in reqs[-2000:]:
                if r.get("endpoint") != endpoint:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str) or len(ts) < 20:
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.timestamp() >= cutoff:
                        cnt += 1
                except Exception:
                    continue
            if cnt >= 60:
                return _err("RATE_LIMIT", "Rate limit exceeded for user search.", retry_after_seconds=60)
            return None
        except Exception:
            return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        e = _err("VALIDATION_ERROR", "query must be a non-empty string.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    # Business rule: users are not persisted; serve from "upstream".
    # Offline implementation: derive candidate user logins from existing mirrored data.
    repos = _load("gh_repositories.json")
    issues = _load("gh_issues.json")
    prs = _load("gh_pull_requests.json")
    commits = _load("gh_commits.json")

    if not isinstance(repos, list): repos = []
    if not isinstance(issues, list): issues = []
    if not isinstance(prs, list): prs = []
    if not isinstance(commits, list): commits = []

    candidates = {}  # login -> minimal record
    def _add_login(login, source=None):
        if not isinstance(login, str) or not login:
            return
        if login not in candidates:
            candidates[login] = {
                "login": login,
                "id": None,
                "name": None,
                "type": "User",
                "source": source
            }

    for r in repos:
        if isinstance(r, dict):
            _add_login(r.get("owner_login"), "repository_owner")
    for it in issues:
        if isinstance(it, dict):
            _add_login(it.get("creator_login"), "issue_creator")
            assignees = it.get("assignees")
            if isinstance(assignees, list):
                for a in assignees:
                    _add_login(a, "issue_assignee")
    for pr in prs:
        if isinstance(pr, dict):
            _add_login(pr.get("creator_login"), "pr_creator")
            _add_login(pr.get("merged_by_login"), "pr_merged_by")
    for c in commits:
        if isinstance(c, dict):
            _add_login(c.get("author_login"), "commit_author")

    q = query.strip().lower()
    terms = [t for t in re.split(r"\s+", q) if t]

    users = []
    for login, u in candidates.items():
        hay = (login or "").lower()
        ok = True
        for t in terms:
            if t not in hay:
                ok = False
                break
        if ok:
            users.append(u)

    users.sort(key=lambda u: (u.get("login") or "").lower())

    def _decode_cursor(c):
        if not c:
            return 0
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    offset = _decode_cursor(cursor)
    if offset is None:
        e = _err("VALIDATION_ERROR", "Invalid cursor.")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    total = len(users)
    page = users[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "users": page,
        "page": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "note": "Users are not persisted in this minimal schema; results are derived from mirrored repository/issue/PR/commit logins."
    }
    _log("OK")
    return resp

def get_issue(repository_id=None, issue_number=None, issue_id=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_issue"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_name():
        if os.path.exists(os.path.join(_DB, "gh_request_logs.json")):
            return "gh_request_logs.json"
        if os.path.exists(os.path.join(_DB, "gh_request_log.json")):
            return "gh_request_log.json"
        return "gh_request_logs.json"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_row(status, error_code=None):
        name = _log_name()
        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    # Accept the vendor schema, but tolerate callers accidentally passing a repo id into issue_id (observed in audit).
    repo_pat = re.compile(r"^ghr_[0-9A-Z]{18,}$")
    issue_pat = re.compile(r"^ghi_[0-9A-Z]{18,}$")

    if issue_id is None and (repository_id is None or issue_number is None):
        e = _err("VALIDATION_ERROR", "Provide either issue_id or (repository_id + issue_number).")
        _log_row("error", e["error"]["code"])
        return e

    if issue_id is not None and not isinstance(issue_id, str):
        e = _err("VALIDATION_ERROR", "Malformed issue_id.", field="issue_id")
        _log_row("error", e["error"]["code"])
        return e

    if repository_id is not None and (not isinstance(repository_id, str) or not repo_pat.match(repository_id)):
        e = _err("VALIDATION_ERROR", "Malformed repository_id.", field="repository_id")
        _log_row("error", e["error"]["code"])
        return e

    if issue_number is not None and (not isinstance(issue_number, int) or issue_number < 1):
        e = _err("VALIDATION_ERROR", "issue_number must be an integer >= 1.", field="issue_number")
        _log_row("error", e["error"]["code"])
        return e

    issues = _ensure_list(_load("gh_issues.json"))
    repos = _ensure_list(_load("gh_repositories.json"))

    repo_by_id = {r.get("id"): r for r in repos if isinstance(r, dict) and isinstance(r.get("id"), str)}

    resolved_issue = None

    # Primary resolution path: issue_id points to an issue row id.
    if issue_id is not None and issue_pat.match(issue_id):
        for it in issues:
            if isinstance(it, dict) and it.get("id") == issue_id and it.get("status") != "deleted":
                resolved_issue = it
                break

    # Compatibility path: caller passed a repository_id into issue_id (observed in audit),
    # so resolve by repository_id + issue_number when possible.
    if resolved_issue is None and issue_id is not None and repo_pat.match(issue_id) and issue_number is not None:
        repository_id = repository_id or issue_id

    # Resolve by repository_id + issue_number if present.
    if resolved_issue is None and repository_id is not None and issue_number is not None:
        repo = repo_by_id.get(repository_id)
        if not repo or repo.get("status") == "deleted":
            e = _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)
            _log_row("error", e["error"]["code"])
            return e
        for it in issues:
            if not isinstance(it, dict):
                continue
            if it.get("status") == "deleted":
                continue
            if it.get("repository_id") == repository_id and it.get("number") == issue_number:
                resolved_issue = it
                break

    # If both provided and we found issue by issue_id, ensure it matches repository_id/issue_number if given.
    if resolved_issue is not None and issue_id is not None and issue_pat.match(issue_id):
        if repository_id is not None and resolved_issue.get("repository_id") != repository_id:
            e = _err("VALIDATION_ERROR", "issue_id does not belong to repository_id.", field="issue_id")
            _log_row("error", e["error"]["code"])
            return e
        if issue_number is not None and resolved_issue.get("number") != issue_number:
            e = _err("VALIDATION_ERROR", "issue_id does not match issue_number.", field="issue_number")
            _log_row("error", e["error"]["code"])
            return e

    if resolved_issue is None:
        e = _err("NOT_FOUND", "Issue not found.", repository_id=repository_id, issue_number=issue_number, issue_id=issue_id)
        _log_row("error", e["error"]["code"])
        return e

    # Visibility: ensure repo exists and isn't deleted
    repo = repo_by_id.get(resolved_issue.get("repository_id"))
    if not repo or repo.get("status") == "deleted":
        e = _err("NOT_FOUND", "Repository not found.", repository_id=resolved_issue.get("repository_id"))
        _log_row("error", e["error"]["code"])
        return e

    out = {"issue": resolved_issue, "repository": repo}
    _log_row("ok")
    return out

