        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    if not isinstance(body, str) or body.strip() == "":
        e = _err("VALIDATION_ERROR", "body must be a non-empty string.", field="body")
        _log_row("error", e["error"]["code"])
        return e

    repo_pat = re.compile(r"^ghr_[0-9A-Z]{18,}$")
    issue_pat = re.compile(r"^ghi_[0-9A-Z]{18,}$")

    if issue_id is None and (repository_id is None or issue_number is None):
        e = _err("VALIDATION_ERROR", "Provide either issue_id or (repository_id + issue_number).")
        _log_row("error", e["error"]["code"])
        return e

    if issue_id is not None and not isinstance(issue_id, str):
        e = _err("VALIDATION_ERROR", "Malformed issue_id.", field="issue_id")
        _log_row("error", e["error"]["code"])
        return e

    if repository_id is not None and (not isinstance(repository_id, str) or not repo_pat.match(repository_id)):
        e = _err("VALIDATION_ERROR", "Malformed repository_id.", field="repository_id")
        _log_row("error", e["error"]["code"])
        return e

    if issue_number is not None and (not isinstance(issue_number, int) or issue_number < 1):
        e = _err("VALIDATION_ERROR", "issue_number must be an integer >= 1.", field="issue_number")
        _log_row("error", e["error"]["code"])
        return e

    issues = _ensure_list(_load("gh_issues.json"))
    repos = _ensure_list(_load("gh_repositories.json"))
    repo_by_id = {r.get("id"): r for r in repos if isinstance(r, dict)}

    resolved_issue = None

    # Resolve by issue_id if it looks like an issue id
    if issue_id is not None and issue_pat.match(issue_id):
        for it in issues:
            if isinstance(it, dict) and it.get("id") == issue_id and it.get("status") != "deleted":
                resolved_issue = it
                break

    # Compatibility: caller passed a repo id in issue_id + issue_number
    if resolved_issue is None and issue_id is not None and repo_pat.match(issue_id) and issue_number is not None:
        repository_id = repository_id or issue_id

    if resolved_issue is None and repository_id is not None and issue_number is not None:
        repo = repo_by_id.get(repository_id)
        if not repo or repo.get("status") == "deleted":
            e = _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)
            _log_row("error", e["error"]["code"])
            return e
        for it in issues:
            if not isinstance(it, dict):
                continue
            if it.get("status") == "deleted":
                continue
            if it.get("repository_id") == repository_id and it.get("number") == issue_number:
                resolved_issue = it
                break

    if resolved_issue is None:
        e = _err("NOT_FOUND", "Issue not found in repository.", repository_id=repository_id, issue_number=issue_number)
        _log_row("error", e["error"]["code"])
        return e

    # Locked issues cannot be commented on
    if resolved_issue.get("locked") is True:
        e = _err("UNAUTHORIZED", "Issue is locked and cannot be commented on.", issue_id=resolved_issue.get("id"))
        _log_row("error", e["error"]["code"])
        return e

    # Minimal schema doesn't store comments; persist to a local upstream-simulation file so there is real effect.
    comments_file = "gh_issue_comments.json"
    comments = _ensure_list(_load(comments_file))

    comment_id = "ghic_" + hashlib.sha1(f"{resolved_issue.get('id')}|{time.time_ns()}".encode()).hexdigest()[:22]
    now = _now()
    comment = {
        "id": comment_id,
        "issue_id": resolved_issue.get("id"),
        "repository_id": resolved_issue.get("repository_id"),
        "issue_number": resolved_issue.get("number"),
        "body": body,
        "user_login": resolved_issue.get("creator_login"),  # best-effort; schema has no caller identity
        "created_at": now,
        "updated_at": now,
    }
    comments.append(comment)
    _save(comments_file, comments)

    _log_row("ok")
    return {"comment": comment}

def search_issues(query, repository_id=None, owner_login=None, repository_name=None, state=None, creator_login=None, assignee=None, label=None, status=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    logs = _load("gh_request_logs.json")
    quotas = _load("gh_quotas.json")

    def _finalize(resp):
        dt_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"ghrl_{base64.b32encode(os.urandom(12)).decode('utf-8').rstrip('=')}",
            "endpoint": "search_issues",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": dt_ms,
            "status": "ok" if "error" not in resp else "error",
            "error_code": resp.get("error", {}).get("code") if isinstance(resp, dict) else None,
        })
        _save("gh_request_logs.json", logs)
        return resp

    def _enforce_limits():
        now = datetime.datetime.utcnow()
        per_min = 120
        per_day = 5000
        if quotas and isinstance(quotas, list):
            q = quotas[0] if quotas else {}
            if isinstance(q, dict):
                pm = q.get("per_minute")
                pd = q.get("per_day")
                if isinstance(pm, int) and pm > 0: per_min = pm
                if isinstance(pd, int) and pd > 0: per_day = pd
        window_start = (now - datetime.timedelta(minutes=1)).isoformat() + "Z"
        day_start = (now - datetime.timedelta(days=1)).isoformat() + "Z"
        last_min = [l for l in logs if isinstance(l, dict) and l.get("timestamp", "") >= window_start]
        last_day = [l for l in logs if isinstance(l, dict) and l.get("timestamp", "") >= day_start]
        if len(last_min) >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if len(last_day) >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim = _enforce_limits()
    if lim:
        return _finalize(lim)

    if not isinstance(query, str) or query.strip() == "":
        return _finalize(_err("VALIDATION_ERROR", "query must be a non-empty string"))

    rid_pat = re.compile(r"^ghr_[0-9A-Z]{18,}$")
    if repository_id is not None and (not isinstance(repository_id, str) or not rid_pat.match(repository_id)):
        return _finalize(_err("VALIDATION_ERROR", "repository_id is malformed"))

    if state is not None and state not in ("open", "closed"):
        return _finalize(_err("VALIDATION_ERROR", "state must be 'open' or 'closed'"))
    if status is not None and status not in ("active", "deleted"):
        return _finalize(_err("VALIDATION_ERROR", "status must be 'active' or 'deleted'"))
    if sort is None:
        sort = "updated_at"
    if sort not in ("updated_at", "created_at"):
        return _finalize(_err("VALIDATION_ERROR", "sort must be 'updated_at' or 'created_at'"))
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _finalize(_err("VALIDATION_ERROR", "order must be 'asc' or 'desc'"))
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _finalize(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 100"))
    if cursor is not None and not isinstance(cursor, str):
        return _finalize(_err("VALIDATION_ERROR", "cursor must be a string"))

    repos = _load("gh_repositories.json")
    issues = _load("gh_issues.json")

    repo_by_id = {r.get("id"): r for r in repos if isinstance(r, dict) and isinstance(r.get("id"), str)}
    # Filter repos by owner/name if provided
    allowed_repo_ids = None
    if owner_login is not None:
        if not isinstance(owner_login, str) or owner_login.strip() == "":
            return _finalize(_err("VALIDATION_ERROR", "owner_login must be a non-empty string"))
        allowed_repo_ids = set()
        for r in repos:
            if not isinstance(r, dict): 
                continue
            if r.get("owner_login") == owner_login:
                if repository_name is None or r.get("name") == repository_name:
                    allowed_repo_ids.add(r.get("id"))
        if repository_name is not None and (not isinstance(repository_name, str) or repository_name.strip() == ""):
            return _finalize(_err("VALIDATION_ERROR", "repository_name must be a non-empty string when provided"))
    elif repository_name is not None:
        # repository_name without owner_login is ambiguous
        return _finalize(_err("VALIDATION_ERROR", "repository_name requires owner_login"))

    if repository_id is not None:
        allowed_repo_ids = {repository_id} if allowed_repo_ids is None else (allowed_repo_ids & {repository_id})

    # parse simple qualifiers from query (label:xxx state:open repo:owner/name)
    tokens = query.strip().split()
    free_terms = []
    q_state = None
    q_label = None
    q_repo_full = None
    for tok in tokens:
        if ":" in tok:
            k, v = tok.split(":", 1)
            if k == "state" and v in ("open", "closed"):
                q_state = v
                continue
            if k == "label" and v:
                q_label = v
                continue
            if k == "repo" and v and "/" in v:
                q_repo_full = v
                continue
        free_terms.append(tok)

    if q_state is not None and state is None:
        state = q_state
    if q_label is not None and label is None:
        label = q_label
    if q_repo_full is not None and allowed_repo_ids is None:
        allowed_repo_ids = set(r.get("id") for r in repos if isinstance(r, dict) and r.get("full_name") == q_repo_full)

    # Build candidate list
    def _text(hay):
        return (hay or "").lower()

    terms = [t.lower() for t in free_terms if t.strip() != ""]
    # If no free terms left, treat as match-all within filters
    def _matches_text(issue):
        if not terms:
            return True
        blob = (_text(issue.get("title")) + "\n" + _text(issue.get("body")))
        return all(t in blob for t in terms)

    def _has_label(issue, lab):
        labs = issue.get("labels")
        if lab is None:
            return True
        if labs is None:
            return False
        if not isinstance(labs, list):
            return False
        return any(isinstance(x, str) and x == lab for x in labs)

    def _has_assignee(issue, a):
        if a is None:
            return True
        ass = issue.get("assignees")
        if ass is None:
            return False
        if not isinstance(ass, list):
            return False
        return any(isinstance(x, str) and x == a for x in ass)

    filtered = []
    for it in issues:
        if not isinstance(it, dict):
            continue
        rid = it.get("repository_id")
        if allowed_repo_ids is not None and rid not in allowed_repo_ids:
            continue
        if rid not in repo_by_id:
            continue
        if state is not None and it.get("state") != state:
            continue
        if creator_login is not None:
            if not isinstance(creator_login, str) or creator_login.strip() == "":
                return _finalize(_err("VALIDATION_ERROR", "creator_login must be a non-empty string"))
            if it.get("creator_login") != creator_login:
                continue
        if not _has_assignee(it, assignee):
            continue
        if not _has_label(it, label):
            continue
        if status is not None:
            if it.get("status") != status:
                continue
        # Default: exclude deleted unless explicitly requested by status='deleted'
        if status is None and it.get("status") == "deleted":
            continue
        if not _matches_text(it):
            continue
        filtered.append(it)

    # Sorting
    reverse = (order == "desc")
    def _key(it):
        v = it.get(sort)
        # ISO timestamps sort lexicographically; fallback empty
        return v or ""
    filtered.sort(key=_key, reverse=reverse)

    # Cursor pagination: cursor is base64 of integer offset
    offset = 0
    if cursor:
        try:
            offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8"))
            if offset < 0:
                return _finalize(_err("VALIDATION_ERROR", "cursor is invalid"))
        except Exception:
            return _finalize(_err("VALIDATION_ERROR", "cursor is invalid"))

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8").rstrip("=")

    return _finalize({
        "issues": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    })

