        window_start = (now - datetime.timedelta(minutes=1)).isoformat() + "Z"
        day_start = (now - datetime.timedelta(days=1)).isoformat() + "Z"
        last_min = [l for l in logs if isinstance(l, dict) and l.get("endpoint") == "create_issue" and l.get("timestamp", "") >= window_start]
        last_day = [l for l in logs if isinstance(l, dict) and l.get("endpoint") == "create_issue" and l.get("timestamp", "") >= day_start]
        if len(last_min) >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if len(last_day) >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim = _enforce_limits()
    if lim:
        return _finalize(lim)

    rid_pat = re.compile(r"^ghr_[0-9A-Z]{18,}$")
    if not isinstance(repository_id, str) or not rid_pat.match(repository_id):
        return _finalize(_err("VALIDATION_ERROR", "repository_id is malformed"))
    if not isinstance(title, str) or title.strip() == "":
        return _finalize(_err("VALIDATION_ERROR", "title must be a non-empty string"))
    if body is not None and not isinstance(body, str):
        return _finalize(_err("VALIDATION_ERROR", "body must be a string"))
    if labels is not None:
        if not isinstance(labels, list) or any((not isinstance(x, str)) for x in labels):
            return _finalize(_err("VALIDATION_ERROR", "labels must be an array of strings"))
    if assignees is not None:
        if not isinstance(assignees, list) or any((not isinstance(x, str)) for x in assignees):
            return _finalize(_err("VALIDATION_ERROR", "assignees must be an array of strings"))

    repos = _load("gh_repositories.json")
    repo = None
    for r in repos:
        if isinstance(r, dict) and r.get("id") == repository_id:
            repo = r
            break
    if repo is None:
        return _finalize(_err("NOT_FOUND", "Repository not found"))
    if repo.get("status") != "active":
        return _finalize(_err("INVALID_TRANSITION", "Repository is not active"))

    issues = _load("gh_issues.json")
    # Allocate next issue number uniquely within repo (ignore deleted; number uniqueness still enforced)
    max_num = 0
    for it in issues:
        if isinstance(it, dict) and it.get("repository_id") == repository_id and isinstance(it.get("number"), int):
            if it["number"] > max_num:
                max_num = it["number"]
    number = max_num + 1

    now = datetime.datetime.utcnow().isoformat() + "Z"
    new_id = "ghi_" + base64.b32encode(secrets.token_bytes(12)).decode("utf-8").rstrip("=")
    row = {
        "id": new_id,
        "repository_id": repository_id,
        "github_issue_id": None,
        "number": number,
        "title": title,
        "body": body,
        "labels": labels,
        "assignees": assignees,
        "creator_login": None,
        "state": "open",
        "locked": False,
        "closed_at": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Enforce constraints: unique(repository_id, number)
    for it in issues:
        if isinstance(it, dict) and it.get("repository_id") == repository_id and it.get("number") == number:
            return _finalize(_err("CONFLICT", "Issue number already exists"))

    issues.append(row)
    _save("gh_issues.json", issues)

    return _finalize({"issue": row})

def list_issues(repository_id, state=None, creator_login=None, assignee=None, label=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    logs = _load("gh_request_logs.json")
    quotas = _load("gh_quotas.json")

    def _finalize(resp):
        dt_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"ghrl_{base64.b32encode(os.urandom(12)).decode('utf-8').rstrip('=')}",
            "endpoint": "list_issues",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": dt_ms,
            "status": "ok" if "error" not in resp else "error",
            "error_code": resp.get("error", {}).get("code") if isinstance(resp, dict) else None,
        })
        _save("gh_request_logs.json", logs)
        return resp

    def _enforce_limits():
        now = datetime.datetime.utcnow()
        per_min = 240
        per_day = 10000
        if quotas and isinstance(quotas, list):
            q = quotas[0] if quotas else {}
            if isinstance(q, dict):
                pm = q.get("list_issues_per_minute")
                pd = q.get("list_issues_per_day")
                if isinstance(pm, int) and pm > 0: per_min = pm
                if isinstance(pd, int) and pd > 0: per_day = pd
        window_start = (now - datetime.timedelta(minutes=1)).isoformat() + "Z"
        day_start = (now - datetime.timedelta(days=1)).isoformat() + "Z"
        last_min = [l for l in logs if isinstance(l, dict) and l.get("endpoint") == "list_issues" and l.get("timestamp", "") >= window_start]
        last_day = [l for l in logs if isinstance(l, dict) and l.get("endpoint") == "list_issues" and l.get("timestamp", "") >= day_start]
        if len(last_min) >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if len(last_day) >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim = _enforce_limits()
    if lim:
        return _finalize(lim)

    rid_pat = re.compile(r"^ghr_[0-9A-Z]{18,}$")
    if not isinstance(repository_id, str) or not rid_pat.match(repository_id):
        return _finalize(_err("VALIDATION_ERROR", "repository_id is malformed"))

    if state is not None and state not in ("open", "closed"):
        return _finalize(_err("VALIDATION_ERROR", "state must be 'open' or 'closed'"))
    if sort is None:
        sort = "updated_at"
    if sort not in ("updated_at", "created_at", "number"):
        return _finalize(_err("VALIDATION_ERROR", "sort must be 'updated_at', 'created_at', or 'number'"))
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _finalize(_err("VALIDATION_ERROR", "order must be 'asc' or 'desc'"))
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _finalize(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 100"))
    if cursor is not None and not isinstance(cursor, str):
        return _finalize(_err("VALIDATION_ERROR", "cursor must be a string"))

    repos = _load("gh_repositories.json")
    repo = None
    for r in repos:
        if isinstance(r, dict) and r.get("id") == repository_id:
            repo = r
            break
    if repo is None:
        return _finalize(_err("NOT_FOUND", "Repository not found"))

    issues = _load("gh_issues.json")

    def _has_label(issue, lab):
        if lab is None:
            return True
        labs = issue.get("labels")
        if labs is None:
            return False
        if not isinstance(labs, list):
            return False
        return any(isinstance(x, str) and x == lab for x in labs)

    def _has_assignee(issue, a):
        if a is None:
            return True
        ass = issue.get("assignees")
        if ass is None:
            return False
        if not isinstance(ass, list):
            return False
        return any(isinstance(x, str) and x == a for x in ass)

    if creator_login is not None and (not isinstance(creator_login, str) or creator_login.strip() == ""):
        return _finalize(_err("VALIDATION_ERROR", "creator_login must be a non-empty string"))

    filtered = []
    for it in issues:
        if not isinstance(it, dict):
            continue
        if it.get("repository_id") != repository_id:
            continue
        # Exclude deleted per business rule
        if it.get("status") == "deleted":
            continue
        if state is not None and it.get("state") != state:
            continue
        if creator_login is not None and it.get("creator_login") != creator_login:
            continue
        if not _has_assignee(it, assignee):
            continue
        if not _has_label(it, label):
            continue
        filtered.append(it)

    reverse = (order == "desc")
    def _key(it):
        if sort == "number":
            return it.get("number") if isinstance(it.get("number"), int) else -1
        return it.get(sort) or ""
    filtered.sort(key=_key, reverse=reverse)

    offset = 0
    if cursor:
        try:
            offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8"))
            if offset < 0:
                return _finalize(_err("VALIDATION_ERROR", "cursor is invalid"))
        except Exception:
            return _finalize(_err("VALIDATION_ERROR", "cursor is invalid"))

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8").rstrip("=")

    return _finalize({
        "issues": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    })

def update_issue(issue_id, title=None, body=None, state=None, labels=None, assignees=None, locked=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_issue"
    request_log_file = "gh_request_log.json"

    def _log(status, credential_id=None, error_code=None):
        logs = _load(request_log_file)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"ghrl_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "ts": now,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
        }
        if isinstance(logs, list):
            logs.append(row)
        else:
            logs = [row]
        _save(request_log_file, logs)

    # Ambient auth: no explicit credential param; allow if any repo exists.
    # (No permission model in schema; cannot emit FORBIDDEN. Use UNAUTHORIZED only if store cannot serve.)
    repos = _load("gh_repositories.json")
    if not isinstance(repos, list) or len(repos) == 0:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated context available to serve this request.")

    if not isinstance(issue_id, str) or not re.match(r"^ghi_01H[0-9A-Z]{15,}$", issue_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed issue_id.", field="issue_id")

    if title is not None and not isinstance(title, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid type for title; expected string.", field="title")
    if title is not None and title == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be non-empty.", field="title")

    if body is not None and not isinstance(body, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid type for body; expected string.", field="body")

    if state is not None:
        if not isinstance(state, str) or state not in ("open", "closed"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid state; expected 'open' or 'closed'.", field="state")

    if labels is not None:
        if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid labels; expected array of strings.", field="labels")

    if assignees is not None:
        if not isinstance(assignees, list) or any(not isinstance(x, str) for x in assignees):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid assignees; expected array of strings.", field="assignees")

    if locked is not None and not isinstance(locked, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid locked; expected boolean.", field="locked")

    issues = _load("gh_issues.json")
    if not isinstance(issues, list):
        issues = []

    idx = None
    for i, r in enumerate(issues):
        if isinstance(r, dict) and r.get("id") == issue_id:
            idx = i
            break
    if idx is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)

    issue = issues[idx]

    # Enforce FK to repo (integrity)
    repo_id = issue.get("repository_id")
    if not any(isinstance(r, dict) and r.get("id") == repo_id for r in repos):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Repository for this issue not found.", repository_id=repo_id)

    # Mutations
    changed = False
    if title is not None and title != issue.get("title"):
        issue["title"] = title
        changed = True
    if body is not None and body != issue.get("body"):
        issue["body"] = body
        changed = True
    if labels is not None:
        issue["labels"] = list(labels)
        changed = True
    if assignees is not None:
        issue["assignees"] = list(assignees)
        changed = True
    if locked is not None and locked != issue.get("locked"):
        issue["locked"] = locked
        changed = True

    if state is not None and state != issue.get("state"):
        cur = issue.get("state")
        transitions = {"open": ["closed"], "closed": ["open"]}
        if cur not in transitions or state not in transitions[cur]:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Illegal issue state transition.", from_state=cur, to_state=state)
        issue["state"] = state
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        if state == "closed":
            issue["closed_at"] = now
        else:
            issue["closed_at"] = None
        changed = True

    # Enforce constraint: closed_at is NULL OR state='closed'
    if issue.get("closed_at") is not None and issue.get("state") != "closed":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "closed_at must be NULL unless state is 'closed'.")

    if not changed:
        # Realistic: return current record as-is (idempotent update), not "ok": true.
        _log("ok")
        return {"issue": issue}

    issue["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    issues[idx] = issue
    _save("gh_issues.json", issues)

    _log("ok")
    return {"issue": issue}

def get_issue_comments(issue_id, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_issue_comments"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_name():
        if os.path.exists(os.path.join(_DB, "gh_request_logs.json")):
            return "gh_request_logs.json"
        if os.path.exists(os.path.join(_DB, "gh_request_log.json")):
            return "gh_request_log.json"
        return "gh_request_logs.json"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_row(status, error_code=None):
        name = _log_name()
        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    # The tool schema uses ^ghi_01H..., but datastore uses ghi_01J...; accept broader ghi_ pattern.
    if not isinstance(issue_id, str) or not re.match(r"^ghi_[0-9A-Z]{18,}$", issue_id):
        e = _err("VALIDATION_ERROR", "Malformed issue_id.", field="issue_id")
        _log_row("error", e["error"]["code"])
        return e

    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        _log_row("error", e["error"]["code"])
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")
        _log_row("error", e["error"]["code"])
        return e

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
        _log_row("error", e["error"]["code"])
        return e

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "Invalid order.", field="order")
        _log_row("error", e["error"]["code"])
        return e

    issues = _ensure_list(_load("gh_issues.json"))
    issue_row = None
    for it in issues:
        if isinstance(it, dict) and it.get("id") == issue_id and it.get("status") != "deleted":
            issue_row = it
            break
    if issue_row is None:
        e = _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)
        _log_row("error", e["error"]["code"])
        return e

    comments = _ensure_list(_load("gh_issue_comments.json"))
    filtered = [c for c in comments if isinstance(c, dict) and c.get("issue_id") == issue_id]

    def _key(c):
        v = c.get(sort)
        if isinstance(v, str):
            dt = _parse_iso(v)
            if dt:
                return dt
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    filtered.sort(key=_key, reverse=(order == "desc"))

    start = 0
    if cursor:
        # opaque cursor: "idx_<n>_<sha1prefix>"
        m = re.match(r"^idx_(\d+)_[0-9a-f]{6,}$", cursor)
        if not m:
            e = _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")
            _log_row("error", e["error"]["code"])
            return e
        start = int(m.group(1))
        if start < 0 or start > len(filtered):
            start = len(filtered)

    page = filtered[start:start + limit]
    next_cursor = None
    if start + limit < len(filtered):
        next_cursor = f"idx_{start+limit}_" + hashlib.sha1(f"{issue_id}|{start+limit}".encode()).hexdigest()[:8]

    resp = {
        "comments": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": start + limit < len(filtered),
            "next_cursor": next_cursor,
        }
    }
    _log_row("ok")
    return resp

def get_repository(repository_id, include_readme=None, include_file_structure=None, branch=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
