    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_and_return(resp):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _now()
        row = {
            "id": f"ghrl_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "timestamp": ts,
            "latency_ms": latency_ms,
            "status": "ok" if isinstance(resp, dict) and "error" not in resp else "error",
        }
        if isinstance(resp, dict) and "error" in resp:
            row["error_code"] = resp["error"].get("code")
        log_name = "gh_request_logs.json" if os.path.exists(os.path.join(_DB, "gh_request_logs.json")) else "gh_request_log.json"
        logs = _ensure_list(_load(log_name))
        logs.append(row)
        _save(log_name, logs)
        return resp

    def _enforce_rate_limit():
        log_name = "gh_request_logs.json" if os.path.exists(os.path.join(_DB, "gh_request_logs.json")) else "gh_request_log.json"
        logs = _ensure_list(_load(log_name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if not isinstance(ts, str):
                continue
            dt = _parse_iso(ts)
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        return _log_and_return(rl)

    # Relaxed repository_id validation to match actual datastore ids (which are ghr_01J...).
    if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Za-z]{10,}$", repository_id):
        return _log_and_return(_err("VALIDATION_ERROR", "Malformed repository_id.", field="repository_id"))

    if include_readme is None:
        include_readme = False
    if include_file_structure is None:
        include_file_structure = False
    if not isinstance(include_readme, bool):
        return _log_and_return(_err("VALIDATION_ERROR", "include_readme must be boolean.", field="include_readme"))
    if not isinstance(include_file_structure, bool):
        return _log_and_return(_err("VALIDATION_ERROR", "include_file_structure must be boolean.", field="include_file_structure"))
    if branch is not None and (not isinstance(branch, str) or branch.strip() == ""):
        return _log_and_return(_err("VALIDATION_ERROR", "branch must be a non-empty string when provided.", field="branch"))

    repos = _ensure_list(_load("gh_repositories.json"))
    repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == repository_id and r.get("status") != "deleted"), None)
    if not repo:
        return _log_and_return(_err("NOT_FOUND", "Repository not found.", repository_id=repository_id))

    effective_branch = branch or repo.get("default_branch") or "main"

    refs = _ensure_list(_load("gh_git_refs.json"))
    repo_refs = [r for r in refs if isinstance(r, dict) and r.get("repository_id") == repository_id and r.get("status") == "active"]

    branches = [r for r in repo_refs if r.get("ref_type") == "branch"]
    tags = [r for r in repo_refs if r.get("ref_type") == "tag"]

    out = {"repository": repo, "branches": branches, "tags": tags}

    # README embedding: prefer repo.readme_*; else try gh_files where path matches readme_path
    if include_readme:
        readme = {
            "path": repo.get("readme_path"),
            "sha": repo.get("readme_sha"),
            "content_base64": repo.get("readme_content_base64"),
            "source": "gh_repositories",
        }
        if not readme["content_base64"]:
            files = _ensure_list(_load("gh_files.json"))
            rp = repo.get("readme_path")
            if isinstance(rp, str) and rp.strip():
                cand = next((f for f in files
                             if isinstance(f, dict)
                             and f.get("repository_id") == repository_id
                             and f.get("path") == rp
                             and f.get("status") == "present"
                             and (f.get("branch_name") in (None, effective_branch))), None)
                if cand:
                    readme["sha"] = cand.get("blob_sha") or readme["sha"]
                    readme["content_base64"] = cand.get("content_base64")
                    readme["source"] = "gh_files"
        out["readme"] = readme

    if include_file_structure:
        files = _ensure_list(_load("gh_files.json"))
        repo_files = [f for f in files if isinstance(f, dict) and f.get("repository_id") == repository_id and f.get("status") == "present"]
        # Filter by branch_name if any branch-scoped records exist for this repo/branch;
        # otherwise fall back to branch_name is NULL (default snapshot).
        has_branch_scoped = any(f.get("branch_name") == effective_branch for f in repo_files)
        if has_branch_scoped:
            repo_files = [f for f in repo_files if f.get("branch_name") in (effective_branch,)]
        else:
            repo_files = [f for f in repo_files if f.get("branch_name") is None]

        # Tree listing derived from file paths
        paths = sorted({f.get("path") for f in repo_files if isinstance(f.get("path"), str) and f.get("path")})
        dirs = set()
        for p in paths:
            parts = p.split("/")
            for i in range(1, len(parts)):
                dirs.add("/".join(parts[:i]) + "/")
        tree = [{"type": "dir", "path": d} for d in sorted(dirs)] + [{"type": "file", "path": p} for p in paths]
        out["branch"] = effective_branch
        out["tree"] = tree

    return _log_and_return(out)

def get_commit(repository_id, sha, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_commit"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_name():
        if os.path.exists(os.path.join(_DB, "gh_request_logs.json")):
            return "gh_request_logs.json"
        if os.path.exists(os.path.join(_DB, "gh_request_log.json")):
            return "gh_request_log.json"
        return "gh_request_logs.json"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_row(status, error_code=None):
        name = _log_name()
        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    # repository_id pattern in tool schema is too strict for this datastore; accept ghr_ prefix + base32-ish.
    if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
        e = _err("VALIDATION_ERROR", "Malformed repository_id.", field="repository_id")
        _log_row("error", e["error"]["code"])
        return e

    if not isinstance(sha, str) or len(sha) < 7 or len(sha) > 40 or not re.match(r"^[0-9a-fA-F]{7,40}$", sha):
        e = _err("VALIDATION_ERROR", "sha must be a 7–40 character hex string.", field="sha")
        _log_row("error", e["error"]["code"])
        return e

    repos = _ensure_list(_load("gh_repositories.json"))
    repo = None
    for r in repos:
        if isinstance(r, dict) and r.get("id") == repository_id and r.get("status") != "deleted":
            repo = r
            break
    if repo is None:
        e = _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)
        _log_row("error", e["error"]["code"])
        return e

    commits = _ensure_list(_load("gh_commits.json"))
    sha_l = sha.lower()
    found = None
    # allow abbreviated sha match (unique prefix), but prefer exact
    exact = None
    prefix_matches = []
    for c in commits:
        if not isinstance(c, dict):
            continue
        if c.get("repository_id") != repository_id:
            continue
        csha = c.get("sha")
        if not isinstance(csha, str):
            continue
        csha_l = csha.lower()
        if csha_l == sha_l:
            exact = c
            break
        if csha_l.startswith(sha_l):
            prefix_matches.append(c)
    if exact is not None:
        found = exact
    elif len(prefix_matches) == 1:
        found = prefix_matches[0]
    elif len(prefix_matches) > 1:
        e = _err("CONFLICT", "Ambiguous abbreviated sha; provide a longer sha prefix.", sha=sha)
        _log_row("error", e["error"]["code"])
        return e

    if found is None:
        # per vendor contract: NOT_FOUND if commit cannot be found mirrored for that repository
        e = _err("NOT_FOUND", "Commit not found in repository.", repository_id=repository_id, sha=sha)
        _log_row("error", e["error"]["code"])
        return e

    _log_row("ok")
    return {"commit": found, "repository": repo}

def list_commits(repository_id, branch, limit=None, cursor=None, author_login=None, since=None, until=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_commits"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_row(status, error_code=None):
        log_name = "gh_request_logs.json" if os.path.exists(os.path.join(_DB, "gh_request_logs.json")) else "gh_request_log.json"
        logs = _ensure_list(_load(log_name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(log_name, logs)

    def _enforce_rate_limit():
        log_name = "gh_request_logs.json" if os.path.exists(os.path.join(_DB, "gh_request_logs.json")) else "gh_request_log.json"
        logs = _ensure_list(_load(log_name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_iso_dt(ts) if isinstance(ts, str) else None
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
        e = _err("VALIDATION_ERROR", "repository_id is invalid.", field="repository_id")
        _log_row("error", e["error"]["code"])
        return e
    if not isinstance(branch, str) or not branch.strip():
        e = _err("VALIDATION_ERROR", "branch is invalid.", field="branch")
        _log_row("error", e["error"]["code"])
        return e
    branch = branch.strip()

    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
        _log_row("error", e["error"]["code"])
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        _log_row("error", e["error"]["code"])
        return e

    if author_login is not None and (not isinstance(author_login, str) or not author_login.strip()):
        e = _err("VALIDATION_ERROR", "author_login must be a non-empty string.", field="author_login")
        _log_row("error", e["error"]["code"])
        return e

    if sort is None:
        sort = "committed_at"
    if sort not in ("committed_at", "authored_at"):
        e = _err("VALIDATION_ERROR", "Unsupported sort.", field="sort")
        _log_row("error", e["error"]["code"])
        return e
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "Unsupported order.", field="order")
        _log_row("error", e["error"]["code"])
        return e

    since_dt = None
    until_dt = None
    if since is not None:
        since_dt = _parse_iso_dt(since)
        if since_dt is None:
            e = _err("VALIDATION_ERROR", "since must be an ISO 8601 date-time.", field="since")
            _log_row("error", e["error"]["code"])
            return e
    if until is not None:
        until_dt = _parse_iso_dt(until)
        if until_dt is None:
            e = _err("VALIDATION_ERROR", "until must be an ISO 8601 date-time.", field="until")
            _log_row("error", e["error"]["code"])
            return e

    repos = _ensure_list(_load("gh_repositories.json"))
    repo = None
    for r in repos:
        if isinstance(r, dict) and r.get("id") == repository_id and r.get("status") != "deleted":
            repo = r
            break
    if not repo:
        e = _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)
        _log_row("error", e["error"]["code"])
        return e

    refs = _ensure_list(_load("gh_git_refs.json"))
    head_sha = None
    for ref in refs:
        if not isinstance(ref, dict):
            continue
        if ref.get("repository_id") == repository_id and ref.get("ref_type") == "branch" and ref.get("status") == "active" and ref.get("name") == branch:
            if isinstance(ref.get("head_commit_sha"), str):
                head_sha = ref.get("head_commit_sha").lower()
            break
    if head_sha is None:
        e = _err("NOT_FOUND", "Branch not found.", repository_id=repository_id, branch=branch)
        _log_row("error", e["error"]["code"])
        return e

    commits = [c for c in _ensure_list(_load("gh_commits.json")) if isinstance(c, dict) and c.get("repository_id") == repository_id]

    # Build map for walking parents if possible
    sha_map = {}
    for c in commits:
        csha = c.get("sha")
        if isinstance(csha, str):
            sha_map[csha.lower()] = c

    ordered = []
    seen = set()
    cur = head_sha
    # walk up to a bounded number to avoid infinite loops on bad data
    for _ in range(2000):
        if not cur or cur in seen:
            break
        seen.add(cur)
        c = sha_map.get(cur)
        if not c:
            break
        ordered.append(c)
        parents = c.get("parent_shas")
        if isinstance(parents, list) and parents:
            p0 = parents[0]
            cur = p0.lower() if isinstance(p0, str) else None
        else:
            break

    # If graph incomplete or empty, fall back to sha ordering (business rule)
    if not ordered:
        ordered = commits[:]

    def _commit_dt(c, field):
        v = c.get(field)
        if isinstance(v, str):
            return _parse_iso_dt(v)
        return None

    # filters
    filtered = []
    for c in ordered:
        if author_login is not None:
            al = c.get("author_login")
            if not isinstance(al, str) or al.lower() != author_login.strip().lower():
                continue
        # date range: check either authored_at/committed_at depending on sort field, else either
        dt = _commit_dt(c, sort)
        if dt is None:
            # fallback check the other timestamp
            dt = _commit_dt(c, "committed_at") or _commit_dt(c, "authored_at")
        if since_dt and dt and dt < since_dt:
            continue
        if until_dt and dt and dt > until_dt:
            continue
        filtered.append(c)

    # sort
    def _sort_key(c):
        dt = _commit_dt(c, sort)
        if dt is None:
            # fallback: stable by sha
            s = c.get("sha") if isinstance(c.get("sha"), str) else ""
            return (datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), s)
        s = c.get("sha") if isinstance(c.get("sha"), str) else ""
        return (dt, s)

    filtered.sort(key=_sort_key, reverse=(order == "desc"))

    # pagination cursor: "offset:<n>"
    offset = 0
    if cursor:
        m = re.match(r"^offset:(\d+)$", cursor)
        if not m:
            e = _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")
            _log_row("error", e["error"]["code"])
            return e
        offset = int(m.group(1))

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    resp = {
        "repository_id": repository_id,
        "branch": branch,
        "commits": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort, "order": order},
    }
    _log_row("ok")
    return resp

