    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_or_update_file"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_and_return(resp):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _now()
        row = {
            "id": f"ghrl_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "timestamp": ts,
            "latency_ms": latency_ms,
            "status": "ok" if isinstance(resp, dict) and "error" not in resp else "error",
        }
        if isinstance(resp, dict) and "error" in resp:
            row["error_code"] = resp["error"].get("code")
        log_name = "gh_request_logs.json" if os.path.exists(os.path.join(_DB, "gh_request_logs.json")) else "gh_request_log.json"
        logs = _ensure_list(_load(log_name))
        logs.append(row)
        _save(log_name, logs)
        return resp

    def _enforce_rate_limit():
        log_name = "gh_request_logs.json" if os.path.exists(os.path.join(_DB, "gh_request_logs.json")) else "gh_request_log.json"
        logs = _ensure_list(_load(log_name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if not isinstance(ts, str):
                continue
            dt = _parse_iso(ts)
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        return _log_and_return(rl)

    # Validate
    if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Za-z]{10,}$", repository_id):
        return _log_and_return(_err("VALIDATION_ERROR", "repository_id is invalid.", field="repository_id"))
    if not isinstance(branch, str) or branch.strip() == "":
        return _log_and_return(_err("VALIDATION_ERROR", "branch must be a non-empty string.", field="branch"))
    if not isinstance(path, str) or path.strip() == "":
        return _log_and_return(_err("VALIDATION_ERROR", "path must be a non-empty string.", field="path"))
    if not isinstance(message, str) or message.strip() == "":
        return _log_and_return(_err("VALIDATION_ERROR", "message must be a non-empty string.", field="message"))
    if not isinstance(content_base64, str) or content_base64.strip() == "":
        return _log_and_return(_err("VALIDATION_ERROR", "content_base64 must be a non-empty base64 string.", field="content_base64"))
    # Validate base64 content
    try:
        raw = base64.b64decode(content_base64.encode("utf-8"), validate=True)
    except Exception:
        return _log_and_return(_err("VALIDATION_ERROR", "content_base64 is not valid base64.", field="content_base64"))

    if sha is not None:
        if not isinstance(sha, str) or len(sha) != 40 or not re.match(r"^[0-9a-fA-F]{40}$", sha):
            return _log_and_return(_err("VALIDATION_ERROR", "sha must be the current full 40-character hex blob SHA when provided.", field="sha"))

    repos = _ensure_list(_load("gh_repositories.json"))
    repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == repository_id and r.get("status") != "deleted"), None)
    if not repo:
        return _log_and_return(_err("NOT_FOUND", "Repository not found.", repository_id=repository_id))

    files = _ensure_list(_load("gh_files.json"))

    # Unique key: (repository_id, branch_name, path)
    def _match(f):
        return (
            isinstance(f, dict)
            and f.get("repository_id") == repository_id
            and f.get("path") == path
            and f.get("branch_name") == branch
        )

    existing = next((f for f in files if _match(f)), None)
    now = _now()

    # Compute new blob sha deterministically from content (not GitHub-real, but stable and 40 hex)
    new_blob_sha = hashlib.sha1(raw).hexdigest().ljust(40, "0")[:40]
    size_bytes = len(raw)

    # Create a commit representing this change (store requires commits by sha unique per repo)
    commit_sha = hashlib.sha1(f"{repository_id}|{branch}|{path}|{message}|{new_blob_sha}|{now}".encode("utf-8")).hexdigest()
    commit_id = "ghcmt_" + base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("=")

    commits = _ensure_list(_load("gh_commits.json"))
    existing_commit = next((c for c in commits if isinstance(c, dict) and c.get("repository_id") == repository_id and c.get("sha") == commit_sha), None)
    if existing_commit is None:
        commits.append({
            "id": commit_id,
            "repository_id": repository_id,
            "sha": commit_sha,
            "author_login": None,
            "author_name": None,
            "author_email": None,
            "authored_at": now,
            "committer_name": None,
            "committer_email": None,
            "committed_at": now,
            "message": message,
            "parent_shas": [existing.get("last_commit_sha")] if isinstance(existing, dict) and existing.get("last_commit_sha") else None,
            "status": "known",
            "created_at": now,
            "updated_at": now,
        })
        _save("gh_commits.json", commits)

    if existing:
        # Optimistic concurrency check
        if sha is None:
            return _log_and_return(_err("VALIDATION_ERROR", "sha is required when updating an existing file (optimistic concurrency).", rule="provided sha must match current blob_sha"))
        current_sha = existing.get("blob_sha")
        if not isinstance(current_sha, str) or len(current_sha) != 40:
            # if store doesn't have it, treat as conflict to avoid silent overwrite
            return _log_and_return(_err("CONFLICT", "Current file SHA is unknown; cannot update with optimistic concurrency.", rule="existing blob_sha must be known to update"))
        if current_sha.lower() != sha.lower():
            return _log_and_return(_err("CONFLICT", "sha does not match current file blob_sha.", rule="provided sha must equal gh_files.blob_sha", current_sha=current_sha))

        existing["content_base64"] = content_base64
        existing["encoding"] = "base64"
        existing["blob_sha"] = new_blob_sha
        existing["size_bytes"] = size_bytes
        existing["last_commit_sha"] = commit_sha
        existing["status"] = "present"
        existing["updated_at"] = now
        _save("gh_files.json", files)
        return _log_and_return({"file": existing, "commit": {"sha": commit_sha}})
    else:
        fid = "ghf_" + base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("=")
        row = {
            "id": fid,
            "repository_id": repository_id,
            "path": path,
            "branch_name": branch,
            "blob_sha": new_blob_sha,
            "size_bytes": size_bytes,
            "encoding": "base64",
            "content_base64": content_base64,
            "last_commit_sha": commit_sha,
            "status": "present",
            "created_at": now,
            "updated_at": now,
        }
        files.append(row)
        _save("gh_files.json", files)
        return _log_and_return({"file": row, "commit": {"sha": commit_sha}})

def create_repository(name, visibility, description=None, default_branch=None, readme_path=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, **extra):
        try:
            logs = _load("gh_request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "ghrl_" + hashlib.sha1(f"create_repository|{now}|{time.time_ns()}".encode()).hexdigest()[:20],
                "endpoint": "create_repository",
                "status": status_s,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                **extra
            })
            _save("gh_request_logs.json", logs)
        except Exception:
            pass

    def _rate_limit_check():
        try:
            logs = _load("gh_request_logs.json")
            if not isinstance(logs, list):
                return None
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= 120:
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
            return None
        except Exception:
            return None

    rl = _rate_limit_check()
    if rl:
        _log("error", error=rl["error"])
        return rl

    # ---- validation ----
    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "name is required.")
        _log("error", error=e["error"])
        return e
    if "/" in name.strip():
        e = _err("VALIDATION_ERROR", "name must not include an owner (no '/').")
        _log("error", error=e["error"])
        return e
    if not isinstance(visibility, str) or visibility not in ("public", "private", "internal"):
        e = _err("VALIDATION_ERROR", "visibility must be one of: public, private, internal.")
        _log("error", error=e["error"])
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string when provided.")
        _log("error", error=e["error"])
        return e
    if default_branch is not None and (not isinstance(default_branch, str) or not default_branch.strip()):
        e = _err("VALIDATION_ERROR", "default_branch must be a non-empty string when provided.")
        _log("error", error=e["error"])
        return e
    if readme_path is not None and (not isinstance(readme_path, str) or not readme_path.strip()):
        e = _err("VALIDATION_ERROR", "readme_path must be a non-empty string when provided.")
        _log("error", error=e["error"])
        return e
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.")
        _log("error", error=e["error"])
        return e

    repos = _load("gh_repositories.json")
    # Determine owner_login: no user store, so use a stable default owner.
    owner_login = "local"

    full_name = f"{owner_login}/{name.strip()}"

    # unique(full_name)
    if any(r.get("full_name") == full_name for r in repos):
        e = _err("CONFLICT", "A repository with this full_name already exists.", full_name=full_name)
        _log("error", error=e["error"])
        return e

    # github_repo_id unique when not null; we won't set it here (unknown)
    repo_id = "ghr_01H" + hashlib.sha1(f"{full_name}|{time.time_ns()}".encode()).hexdigest().upper()[:18]

    row = {
        "id": repo_id,
        "github_repo_id": None,
        "owner_login": owner_login,
        "name": name.strip(),
        "full_name": full_name,
        "description": description if description is not None else None,
        "visibility": visibility,
        "default_branch": default_branch if default_branch is not None else None,
        "is_fork": False,
        "parent_repository_id": None,
        "readme_path": readme_path if readme_path is not None else None,
        "readme_sha": None,
        "readme_content_base64": None,
        "status": status,
        "created_at": now,
        "updated_at": now,
    }

    repos.append(row)
    _save("gh_repositories.json", repos)

    resp = {"repository": row}
    _log("ok")
    return resp

def get_file_contents(repository_id, path, ref=None, **_extra):
    import json, os, datetime, re, base64, hashlib, random, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    req_log_file = "gh_request_log.json"

    def _log(status, meta=None):
        logs = _load(req_log_file)
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"ghrl_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "get_file_contents",
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": ts,
            "repository_id": repository_id,
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save(req_log_file, logs)

    try:
        if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "repository_id is invalid.")
        if not isinstance(path, str) or path.strip() == "" or path.startswith("/") or ".." in path.split("/"):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "path is invalid.")
        if ref is not None and (not isinstance(ref, str) or ref.strip() == ""):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "ref is malformed.")

        repos = _load("gh_repositories.json")
        repo = next((r for r in repos if r.get("id") == repository_id), None)
        if not repo or repo.get("status") == "deleted":
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Repository not found.")

        # "FORBIDDEN" is mentioned, but contract codes don't include it. Use UNAUTHORIZED.
        if repo.get("visibility") in ("private", "internal"):
            # Ambient auth: if the system has any repo rows at all, treat as authorized.
            # Only deny if datastore indicates no access mechanism; none exists in schema,
            # so never deny well-formed calls.
            pass

        effective_ref = ref if ref else repo.get("default_branch")
        if not effective_ref or not isinstance(effective_ref, str) or effective_ref.strip() == "":
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Ref could not be resolved (no default branch and ref omitted).")

        git_refs = _load("gh_git_refs.json")
        commits = _load("gh_commits.json")
        files = _load("gh_files.json")

        def _is_sha(s):
            return isinstance(s, str) and re.fullmatch(r"[0-9a-f]{40}", s) is not None

        # Resolve ref -> branch_name context for file lookup; accept commit SHA/tag/branch.
        branch_ctx = None
        resolved_commit_sha = None

        if _is_sha(effective_ref):
            resolved_commit_sha = effective_ref
        else:
            # Prefer active branch by name, then active tag by name, then full_ref exact.
            br = next((gr for gr in git_refs
                       if gr.get("repository_id") == repository_id
                       and gr.get("status") == "active"
                       and gr.get("ref_type") == "branch"
                       and gr.get("name") == effective_ref), None)
            if br:
                branch_ctx = br.get("name")
                resolved_commit_sha = br.get("head_commit_sha")
            else:
                tg = next((gr for gr in git_refs
                           if gr.get("repository_id") == repository_id
                           and gr.get("status") == "active"
                           and gr.get("ref_type") == "tag"
                           and gr.get("name") == effective_ref), None)
                if tg:
                    resolved_commit_sha = tg.get("head_commit_sha") or tg.get("tag_object_sha")
                else:
                    gr2 = next((gr for gr in git_refs
                                if gr.get("repository_id") == repository_id
                                and gr.get("status") == "active"
                                and gr.get("full_ref") == effective_ref), None)
                    if gr2:
                        if gr2.get("ref_type") == "branch":
                            branch_ctx = gr2.get("name")
                        resolved_commit_sha = gr2.get("head_commit_sha") or gr2.get("tag_object_sha")
                    else:
                        _log("error", {"error_code": "NOT_FOUND"})
                        return _err("NOT_FOUND", "Ref not found.")

        # Try to locate file record by (repo, path, branch_name) first, then branch_name NULL.
        candidates = []
        if branch_ctx is not None:
            candidates = [f for f in files
                          if f.get("repository_id") == repository_id
                          and f.get("path") == path
                          and f.get("branch_name") == branch_ctx]
        if not candidates:
            candidates = [f for f in files
                          if f.get("repository_id") == repository_id
                          and f.get("path") == path
                          and f.get("branch_name") is None]
        if not candidates:
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "File not found.")
        frow = candidates[0]
        if frow.get("status") != "present":
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "File not found (deleted).")

        # If content missing, "fetch from upstream" (offline): synthesize deterministic content and update cache.
        if frow.get("content_base64") is None:
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            # Deterministic bytes derived from repo/path/ref
            seed = (repository_id + "|" + path + "|" + (effective_ref or "") + "|" + (resolved_commit_sha or "")).encode("utf-8")
            blob = hashlib.sha1(seed).hexdigest()  # 40 hex chars
            content_bytes = (f"// fetched:{now}\n// repo:{repo.get('full_name')}\n// path:{path}\n// ref:{effective_ref}\n").encode("utf-8")
            b64 = base64.b64encode(content_bytes).decode("ascii")
            frow["content_base64"] = b64
            frow["encoding"] = "base64"
            frow["blob_sha"] = blob
            frow["size_bytes"] = len(content_bytes)
            frow["updated_at"] = now
            if resolved_commit_sha and _is_sha(resolved_commit_sha):
                frow["last_commit_sha"] = resolved_commit_sha

            # Persist update to the matched row (by id)
            for i, ff in enumerate(files):
                if ff.get("id") == frow.get("id"):
                    files[i] = frow
                    break
            _save("gh_files.json", files)

        # Build response
        resp = {
            "repository_id": repository_id,
            "path": frow.get("path"),
            "ref": effective_ref,
            "branch_name": frow.get("branch_name") if frow.get("branch_name") is not None else branch_ctx,
            "blob_sha": frow.get("blob_sha"),
            "size_bytes": frow.get("size_bytes"),
            "encoding": frow.get("encoding"),
            "content_base64": frow.get("content_base64"),
            "last_commit_sha": frow.get("last_commit_sha"),
            "updated_at": frow.get("updated_at"),
            "created_at": frow.get("created_at"),
        }
        _log("ok")
        return {"data": resp}
    except Exception as e:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def fork_repository(repository_id, organization=None, name=None, default_branch_only=None, **_extra):
    import json, os, datetime, re, random, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    req_log_file = "gh_request_log.json"

    def _log(status, meta=None):
        logs = _load(req_log_file)
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"ghrl_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "fork_repository",
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": ts,
            "repository_id": repository_id,
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save(req_log_file, logs)

    try:
        if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "repository_id is invalid.")
        if organization is not None and (not isinstance(organization, str) or organization.strip() == "" or "/" in organization):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "organization is invalid.")
        if name is not None and (not isinstance(name, str) or name.strip() == "" or "/" in name):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name is invalid.")
        if default_branch_only is not None and not isinstance(default_branch_only, bool):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "default_branch_only must be boolean.")

        repos = _load("gh_repositories.json")
        src = next((r for r in repos if r.get("id") == repository_id), None)
        if not src or src.get("status") != "active":
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Source repository not found or not active.")

        fork_owner = (organization.strip() if organization else "authenticated_user")
        fork_name = (name.strip() if name else src.get("name"))
        if not fork_name or not isinstance(fork_name, str) or fork_name.strip() == "":
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Fork name resolved to empty.")

        full_name = f"{fork_owner}/{fork_name}"

        # Enforce unique(full_name)
        if any(r.get("full_name") == full_name for r in repos):
            _log("error", {"error_code": "CONFLICT"})
            return _err("CONFLICT", "A repository with the target full_name already exists.", full_name=full_name)

        # Create new repo row
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        new_id = f"ghr_{int(time.time()*1000)}{random.randint(100000,999999)}"
        new_id = re.sub(r"[^0-9A-Z_]", "", new_id.upper())
        # ensure length >= 22-ish after ghr_
        if len(new_id) < 22:
            new_id = new_id + ("0" * (22 - len(new_id)))

        new_repo = {
            "id": new_id,
            "github_repo_id": None,
            "owner_login": fork_owner,
            "name": fork_name,
            "full_name": full_name,
            "description": src.get("description"),
            "visibility": src.get("visibility"),
            "default_branch": src.get("default_branch"),
            "is_fork": True,
            "parent_repository_id": src.get("id"),
            "readme_path": src.get("readme_path"),
            "readme_sha": src.get("readme_sha"),
            "readme_content_base64": src.get("readme_content_base64"),
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }

        repos.append(new_repo)
        _save("gh_repositories.json", repos)

        # Optionally fork refs/files. Schema doesn't require deep copy; keep minimal.
        if default_branch_only is True and src.get("default_branch"):
            refs = _load("gh_git_refs.json")
            files = _load("gh_files.json")
            # Copy default branch ref if present
            src_branch = next((gr for gr in refs
                               if gr.get("repository_id") == src.get("id")
                               and gr.get("ref_type") == "branch"
                               and gr.get("status") == "active"
                               and gr.get("name") == src.get("default_branch")), None)
            if src_branch:
