                    "name": src_branch.get("name"),
                    "full_ref": f"refs/heads/{src_branch.get('name')}",
                    "head_commit_sha": src_branch.get("head_commit_sha"),
                    "tag_object_sha": None,
                    "tag_message": None,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now,
                })
                _save("gh_git_refs.json", refs)

            # Copy files with matching branch_name or NULL
            to_copy = [f for f in files if f.get("repository_id") == src.get("id") and
                       (f.get("branch_name") in (None, src.get("default_branch")))]
            if to_copy:
                for f in to_copy:
                    files.append({
                        "id": f"ghf_{int(time.time()*1000)}_{random.randint(1000,9999)}",
