        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def create_branch(repository_id, branch_name, from_ref=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_branch"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_name():
        if os.path.exists(os.path.join(_DB, "gh_request_logs.json")):
            return "gh_request_logs.json"
        if os.path.exists(os.path.join(_DB, "gh_request_log.json")):
            return "gh_request_log.json"
        return "gh_request_logs.json"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_row(status, error_code=None):
        name = _log_name()
        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
        e = _err("VALIDATION_ERROR", "Malformed repository_id.", field="repository_id")
        _log_row("error", e["error"]["code"])
        return e

    if not isinstance(branch_name, str) or branch_name.strip() == "":
        e = _err("VALIDATION_ERROR", "branch_name must be a non-empty string.", field="branch_name")
        _log_row("error", e["error"]["code"])
        return e

    if from_ref is not None and (not isinstance(from_ref, str) or from_ref.strip() == ""):
        e = _err("VALIDATION_ERROR", "from_ref must be a non-empty string when provided.", field="from_ref")
        _log_row("error", e["error"]["code"])
        return e

    repos = _ensure_list(_load("gh_repositories.json"))
    repo = None
    for r in repos:
        if isinstance(r, dict) and r.get("id") == repository_id and r.get("status") == "active":
            repo = r
            break
    if repo is None:
        e = _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)
        _log_row("error", e["error"]["code"])
        return e

    refs = _ensure_list(_load("gh_git_refs.json"))
    # conflict if branch exists (even if deleted? treat deleted as conflict? GitHub allows recreation; here allow if deleted)
    for ref in refs:
        if not isinstance(ref, dict):
            continue
        if ref.get("repository_id") == repository_id and ref.get("ref_type") == "branch" and ref.get("name") == branch_name:
            if ref.get("status") == "active":
                e = _err("CONFLICT", "Branch already exists.", branch_name=branch_name)
                _log_row("error", e["error"]["code"])
                return e
            # if deleted, we will "recreate" by transitioning deleted->active is not allowed by lifecycle.
            # so we create a new row and leave old deleted row untouched.

    # Resolve from_ref
    source_sha = None
    if from_ref is None:
        from_ref = repo.get("default_branch") or "main"

    # from_ref can be a commit sha, branch, or tag
    if re.match(r"^[0-9a-fA-F]{7,40}$", from_ref):
        # allow unknown (business rule); store full 40 if present, else store as None
        if len(from_ref) == 40:
            source_sha = from_ref.lower()
        else:
            # try to resolve abbreviation from commits
            commits = _ensure_list(_load("gh_commits.json"))
            matches = []
            for c in commits:
                if isinstance(c, dict) and c.get("repository_id") == repository_id:
                    csha = c.get("sha")
                    if isinstance(csha, str) and csha.lower().startswith(from_ref.lower()):
                        matches.append(csha.lower())
            if len(matches) == 1:
                source_sha = matches[0]
            elif len(matches) > 1:
                e = _err("CONFLICT", "Ambiguous abbreviated from_ref sha; provide longer sha.", from_ref=from_ref)
                _log_row("error", e["error"]["code"])
                return e
            else:
                source_sha = None
    else:
        # try branch
        src_ref = None
        for ref in refs:
            if not isinstance(ref, dict):
                continue
            if ref.get("repository_id") != repository_id or ref.get("status") != "active":
                continue
            if ref.get("ref_type") == "branch" and ref.get("name") == from_ref:
                src_ref = ref
                break
        # try tag
        if src_ref is None:
            for ref in refs:
                if not isinstance(ref, dict):
                    continue
                if ref.get("repository_id") != repository_id or ref.get("status") != "active":
                    continue
                if ref.get("ref_type") == "tag" and ref.get("name") == from_ref:
                    src_ref = ref
                    break
        if src_ref is None:
            e = _err("NOT_FOUND", "Source ref not found.", repository_id=repository_id, from_ref=from_ref)
            _log_row("error", e["error"]["code"])
            return e
        source_sha = src_ref.get("head_commit_sha")

    now = _now()
    new_id = "ghref_" + hashlib.sha1(f"{repository_id}|branch|{branch_name}|{time.time_ns()}".encode()).hexdigest()[:22]
    new_ref = {
        "id": new_id,
        "repository_id": repository_id,
        "ref_type": "branch",
        "name": branch_name,
        "full_ref": f"refs/heads/{branch_name}",
        "head_commit_sha": source_sha,
        "tag_object_sha": None,
        "tag_message": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Enforce unique(repository_id, ref_type, name) and unique(repository_id, full_ref)
    for ref in refs:
        if not isinstance(ref, dict):
            continue
        if ref.get("repository_id") == repository_id and ref.get("status") == "active":
            if ref.get("ref_type") == "branch" and ref.get("name") == branch_name:
                e = _err("CONFLICT", "Branch already exists.", branch_name=branch_name)
                _log_row("error", e["error"]["code"])
                return e
            if ref.get("full_ref") == new_ref["full_ref"]:
                e = _err("CONFLICT", "Ref already exists.", full_ref=new_ref["full_ref"])
                _log_row("error", e["error"]["code"])
                return e

    refs.append(new_ref)
    _save("gh_git_refs.json", refs)

    _log_row("ok")
    return {"ref": new_ref, "repository": repo}

def list_tags(repository_id, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, random, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    req_log_file = "gh_request_log.json"

    def _log(status, meta=None):
        logs = _load(req_log_file)
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"ghrl_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "list_tags",
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": ts,
            "repository_id": repository_id,
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save(req_log_file, logs)

    try:
        if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "repository_id is invalid.")
        if limit is None:
            limit = 30
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
        if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        if sort is None:
            sort = "name"
        if sort not in ("name", "updated_at", "created_at"):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unsupported sort.")
        if order is None:
            order = "asc"
        if order not in ("asc", "desc"):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unsupported order.")

        repos = _load("gh_repositories.json")
        repo = next((r for r in repos if r.get("id") == repository_id), None)
        if not repo or repo.get("status") == "deleted":
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Repository not found.")

        refs = _load("gh_git_refs.json")
        tags = [r for r in refs if r.get("repository_id") == repository_id and r.get("ref_type") == "tag" and r.get("status") == "active"]

        reverse = (order == "desc")
        def _key(x):
            v = x.get(sort)
            return (v is None, v)
        tags.sort(key=_key, reverse=reverse)

        start = 0
        if cursor is not None:
            m = re.fullmatch(r"offset:(\d+)", cursor.strip())
            if not m:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is malformed.")
            start = int(m.group(1))
            if start < 0:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is malformed.")

        total = len(tags)
        page = tags[start:start + limit]
        next_cursor = None
        if start + limit < total:
            next_cursor = f"offset:{start + limit}"

        _log("ok")
        return {
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor,
                "sort": sort,
                "order": order,
            },
        }
    except Exception as e:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

