def update_pull_request(repository_id, pull_request_number, title=None, body=None, state=None, base_branch=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_file = "gh_usage.json"
    usage = _load(usage_file)
    def _log(status, code=None, message=None):
        row = {
            "id": f"ghu_{int(time.time()*1000)}_{os.getpid()}_{len(usage)+1}",
            "endpoint": "update_pull_request",
            "status": status,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        usage.append(row)
        _save(usage_file, usage)

    try:
        if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
            _log("error", "VALIDATION_ERROR", "Invalid repository_id.")
            return _err("VALIDATION_ERROR", "Invalid repository_id.")
        if not isinstance(pull_request_number, int) or pull_request_number < 1:
            _log("error", "VALIDATION_ERROR", "Invalid pull_request_number.")
            return _err("VALIDATION_ERROR", "Invalid pull_request_number.")

        # validate optional fields
        any_change = False
        if title is not None:
            if not isinstance(title, str) or title == "":
                _log("error", "VALIDATION_ERROR", "title must be a non-empty string when provided.")
                return _err("VALIDATION_ERROR", "title must be a non-empty string when provided.")
            any_change = True
        if body is not None:
            if not isinstance(body, str):
                _log("error", "VALIDATION_ERROR", "body must be a string when provided.")
                return _err("VALIDATION_ERROR", "body must be a string when provided.")
            any_change = True
        if state is not None:
            if state not in ("open", "closed"):
                _log("error", "VALIDATION_ERROR", "state must be 'open' or 'closed' when provided.")
                return _err("VALIDATION_ERROR", "state must be 'open' or 'closed' when provided.")
            any_change = True
        if base_branch is not None:
            if not isinstance(base_branch, str) or not base_branch.strip():
                _log("error", "VALIDATION_ERROR", "base_branch must be a non-empty string when provided.")
                return _err("VALIDATION_ERROR", "base_branch must be a non-empty string when provided.")
            any_change = True

        if not any_change:
            _log("error", "VALIDATION_ERROR", "No updatable fields provided.")
            return _err("VALIDATION_ERROR", "No updatable fields provided.")

        repos = _load("gh_repositories.json")
        repo = next((r for r in repos if r.get("id") == repository_id), None)
        if not repo or repo.get("status") == "deleted":
            _log("error", "NOT_FOUND", "Repository not found.")
            return _err("NOT_FOUND", "Repository not found.")

        prs = _load("gh_pull_requests.json")
        pr = next(
            (p for p in prs
             if p.get("repository_id") == repository_id
             and p.get("number") == pull_request_number
             and p.get("status") != "deleted"),
            None
        )
        if not pr:
            _log("error", "NOT_FOUND", "Pull request not found.")
            return _err("NOT_FOUND", "Pull request not found.")

        # Prevent setting merged directly, and prevent transitions out of merged
        current_state = pr.get("state")
        if current_state == "merged":
            if state is not None and state != "merged":
                _log("error", "INVALID_TRANSITION", "Cannot change state of a merged pull request.")
                return _err("INVALID_TRANSITION", "Cannot change state of a merged pull request.")
            # allow title/body/base edits? GitHub typically allows edits to title/body after merge; we'll allow.
        if state is not None:
            if state == "open" and current_state not in ("closed", "open"):
                _log("error", "INVALID_TRANSITION", "Invalid state transition.")
                return _err("INVALID_TRANSITION", "Invalid state transition.")
            if state == "closed" and current_state not in ("open", "closed"):
                _log("error", "INVALID_TRANSITION", "Invalid state transition.")
                return _err("INVALID_TRANSITION", "Invalid state transition.")
            # Schema transitions: open -> closed, closed -> open, merged -> []
            if current_state == "open" and state == "open":
                pass
            elif current_state == "closed" and state == "closed":
                pass
            elif current_state == "open" and state == "closed":
                pass
            elif current_state == "closed" and state == "open":
                pass
            else:
                _log("error", "INVALID_TRANSITION", "Invalid state transition.")
                return _err("INVALID_TRANSITION", "Invalid state transition.")

        # Base retargeting: if provided, ensure it exists as active branch ref OR allow but set review_status unknown
        if base_branch is not None and base_branch != pr.get("base_branch"):
            refs = _load("gh_git_refs.json")
            base_exists = any(
                r.get("repository_id") == repository_id and r.get("ref_type") == "branch"
                and r.get("name") == base_branch and r.get("status") == "active"
                for r in refs
            )
            pr["base_branch"] = base_branch
            if not base_exists:
                pr["review_status"] = "unknown"

        if title is not None:
            pr["title"] = title
        if body is not None:
            pr["body"] = body
        if state is not None:
            # update_pull_request must not set merged directly; tool schema doesn't even allow it.
            pr["state"] = state
            # if closing, keep merged fields untouched (they should be null unless merged by merge tool)
            if state != "merged":
                pr["merged_at"] = None
                pr["merged_by_login"] = None
                pr["merge_commit_sha"] = None

        pr["updated_at"] = now

        _save("gh_pull_requests.json", prs)

        out = {
            "repository": {
                "id": repo.get("id"),
                "full_name": repo.get("full_name"),
                "visibility": repo.get("visibility"),
            },
            "pull_request": pr
        }
        _log("ok")
        return out
    except Exception as e:
        _log("error", "VALIDATION_ERROR", "Unexpected error.")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def list_pull_requests(repository_id, state=None, creator_login=None, base_branch=None, head_branch=None, review_status=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_pull_requests"
    status_code = "ok"

    def _log(status_code, error_code=None, error_message=None):
        try:
            logs = _load("gh_request_log.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            latency_ms = int((time.time() - _t0) * 1000)
            row = {
                "id": f"ghrl_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "ts": now,
                "endpoint": endpoint,
                "status": status_code,
                "latency_ms": latency_ms,
            }
            if error_code:
                row["error_code"] = error_code
            if error_message:
                row["error_message"] = error_message
            logs.append(row)
            _save("gh_request_log.json", logs)
        except Exception:
            pass

    try:
        if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
            status_code = "error"
            _log(status_code, "VALIDATION_ERROR", "Invalid repository_id.")
            return _err("VALIDATION_ERROR", "Invalid repository_id.")
        if state is not None and state not in ("open", "closed", "merged"):
            status_code = "error"
            _log(status_code, "VALIDATION_ERROR", "Invalid state.")
            return _err("VALIDATION_ERROR", "Invalid state.")
        if review_status is not None and review_status not in ("unknown", "clean", "dirty", "blocked", "draft"):
            status_code = "error"
            _log(status_code, "VALIDATION_ERROR", "Invalid review_status.")
            return _err("VALIDATION_ERROR", "Invalid review_status.")
        if sort is not None and sort not in ("created_at", "updated_at", "number"):
            status_code = "error"
            _log(status_code, "VALIDATION_ERROR", "Invalid sort.")
            return _err("VALIDATION_ERROR", "Invalid sort.")
        if order is not None and order not in ("asc", "desc"):
            status_code = "error"
            _log(status_code, "VALIDATION_ERROR", "Invalid order.")
            return _err("VALIDATION_ERROR", "Invalid order.")
        if limit is None:
            limit = 30
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            status_code = "error"
            _log(status_code, "VALIDATION_ERROR", "Invalid limit.")
            return _err("VALIDATION_ERROR", "Invalid limit.", min=1, max=100)

        start = 0
        if cursor is not None:
            if not isinstance(cursor, str) or cursor == "":
                status_code = "error"
                _log(status_code, "VALIDATION_ERROR", "Malformed cursor.")
                return _err("VALIDATION_ERROR", "Malformed cursor.")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
                if not raw.startswith("offset:"):
                    raise ValueError("bad")
                start = int(raw.split(":", 1)[1])
                if start < 0:
                    raise ValueError("bad")
            except Exception:
                status_code = "error"
                _log(status_code, "VALIDATION_ERROR", "Malformed cursor.")
                return _err("VALIDATION_ERROR", "Malformed cursor.")

        repos = _load("gh_repositories.json")
        repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == repository_id), None)
        if not repo:
            status_code = "error"
            _log(status_code, "NOT_FOUND", "Repository not found.")
            return _err("NOT_FOUND", "Repository not found.")
        if repo.get("status") == "deleted":
            status_code = "error"
            _log(status_code, "NOT_FOUND", "Repository not found.")
            return _err("NOT_FOUND", "Repository not found.")

        prs = _load("gh_pull_requests.json")
        if not isinstance(prs, list):
            prs = []

        rows = []
        for pr in prs:
            if not isinstance(pr, dict):
                continue
            if pr.get("repository_id") != repository_id:
                continue
            if pr.get("status") == "deleted":
                continue
            if state is not None and pr.get("state") != state:
                continue
            if creator_login is not None:
                if not isinstance(creator_login, str):
                    status_code = "error"
                    _log(status_code, "VALIDATION_ERROR", "Invalid creator_login.")
                    return _err("VALIDATION_ERROR", "Invalid creator_login.")
                if (pr.get("creator_login") or "") != creator_login:
                    continue
            if base_branch is not None:
                if not isinstance(base_branch, str):
                    status_code = "error"
                    _log(status_code, "VALIDATION_ERROR", "Invalid base_branch.")
                    return _err("VALIDATION_ERROR", "Invalid base_branch.")
                if (pr.get("base_branch") or "") != base_branch:
                    continue
            if head_branch is not None:
                if not isinstance(head_branch, str):
                    status_code = "error"
                    _log(status_code, "VALIDATION_ERROR", "Invalid head_branch.")
                    return _err("VALIDATION_ERROR", "Invalid head_branch.")
                if (pr.get("head_branch") or "") != head_branch:
                    continue
            if review_status is not None and pr.get("review_status") != review_status:
                continue
            rows.append(pr)

        sort_field = sort or "updated_at"
        reverse = (order or "desc") == "desc"

        def _key(x):
            v = x.get(sort_field)
            if sort_field in ("created_at", "updated_at"):
                if isinstance(v, str):
                    return v
                return ""
            if sort_field == "number":
                try:
                    return int(v)
                except Exception:
                    return -1
            return v

        rows.sort(key=_key, reverse=reverse)

        total = len(rows)
        page = rows[start:start + limit]
        next_cursor = None
        has_more = start + limit < total
        if has_more:
            next_cursor = base64.urlsafe_b64encode(f"offset:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

        resp = {
            "pull_requests": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more
            },
            "sort": {"field": sort_field, "order": "desc" if reverse else "asc"},
        }
        _log(status_code)
        return resp
    except Exception as e:
        status_code = "error"
        _log(status_code, "VALIDATION_ERROR", "Unexpected error.")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def merge_pull_request(pull_request_id, commit_title=None, commit_message=None, merge_method=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "merge_pull_request"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_name():
        if os.path.exists(os.path.join(_DB, "gh_request_logs.json")):
            return "gh_request_logs.json"
        if os.path.exists(os.path.join(_DB, "gh_request_log.json")):
            return "gh_request_log.json"
        return "gh_request_logs.json"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_row(status, error_code=None):
        name = _log_name()
        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    if not isinstance(pull_request_id, str) or not re.match(r"^ghpr_[0-9A-Z]{18,}$", pull_request_id):
        e = _err("VALIDATION_ERROR", "Invalid pull_request_id.", field="pull_request_id")
        _log_row("error", e["error"]["code"])
        return e

    if merge_method is None:
        merge_method = "merge"
    if merge_method not in ("merge", "squash", "rebase"):
        e = _err("VALIDATION_ERROR", "Invalid merge_method.", field="merge_method")
        _log_row("error", e["error"]["code"])
        return e

    if commit_title is not None and (not isinstance(commit_title, str) or commit_title.strip() == ""):
        e = _err("VALIDATION_ERROR", "commit_title must be a non-empty string when provided.", field="commit_title")
        _log_row("error", e["error"]["code"])
        return e

    if commit_message is not None and (not isinstance(commit_message, str) or commit_message.strip() == ""):
        e = _err("VALIDATION_ERROR", "commit_message must be a non-empty string when provided.", field="commit_message")
        _log_row("error", e["error"]["code"])
        return e

    prs = _ensure_list(_load("gh_pull_requests.json"))
    pr = None
    pr_idx = None
    for i, p in enumerate(prs):
        if isinstance(p, dict) and p.get("id") == pull_request_id and p.get("status") != "deleted":
            pr = p
            pr_idx = i
            break
    if pr is None:
        e = _err("NOT_FOUND", "Pull request not found.", pull_request_id=pull_request_id)
        _log_row("error", e["error"]["code"])
        return e

    if pr.get("state") != "open":
        e = _err("CONFLICT", "Pull request is not open and cannot be merged.", state=pr.get("state"))
        _log_row("error", e["error"]["code"])
        return e

    if pr.get("mergeable") is False:
        e = _err("CONFLICT", "Pull request is not mergeable.", mergeable=False)
        _log_row("error", e["error"]["code"])
        return e

    repository_id = pr.get("repository_id")
    if not isinstance(repository_id, str):
        e = _err("NOT_FOUND", "Repository not found for pull request.", pull_request_id=pull_request_id)
        _log_row("error", e["error"]["code"])
        return e

    now = _now()
    merge_commit_sha = hashlib.sha1(f"merge|{pull_request_id}|{merge_method}|{commit_title}|{commit_message}|{time.time_ns()}".encode()).hexdigest()[:40].lower()

    # Update PR state (lifecycle transition open -> merged allowed)
    pr["state"] = "merged"
    pr["merged_at"] = now
    pr["merge_commit_sha"] = merge_commit_sha
    pr["merged_by_login"] = pr.get("merged_by_login") or pr.get("creator_login")
    pr["updated_at"] = now

    # Insert/Upsert commit in gh_commits for the repository
    commits = _ensure_list(_load("gh_commits.json"))
    existing_commit = None
    for c in commits:
        if isinstance(c, dict) and c.get("repository_id") == repository_id and (c.get("sha") or "").lower() == merge_commit_sha:
            existing_commit = c
            break
    if existing_commit is None:
        msg = commit_message or pr.get("title") or "Merge pull request"
        commit_row = {
            "id": "ghcmt_" + hashlib.sha1(f"{repository_id}|{merge_commit_sha}".encode()).hexdigest()[:22],
            "repository_id": repository_id,
            "sha": merge_commit_sha,
            "author_login": pr.get("merged_by_login"),
            "author_name": None,
            "author_email": None,
            "authored_at": now,
            "committer_name": None,
            "committer_email": None,
            "committed_at": now,
            "message": msg,
            "parent_shas": [],
            "status": "known",
            "created_at": now,
            "updated_at": now,
        }
        commits.append(commit_row)
    else:
        existing_commit["updated_at"] = now

    prs[pr_idx] = pr
    _save("gh_pull_requests.json", prs)
    _save("gh_commits.json", commits)

    _log_row("ok")
    return {"pull_request": pr, "merge": {"merge_method": merge_method, "merge_commit_sha": merge_commit_sha}}

