        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    if not isinstance(pull_request_id, str) or not re.match(r"^ghpr_[0-9A-Z]{18,}$", pull_request_id):
        e = _err("VALIDATION_ERROR", "Invalid pull_request_id.", field="pull_request_id")
        _log_row("error", e["error"]["code"])
        return e

    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        _log_row("error", e["error"]["code"])
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")
        _log_row("error", e["error"]["code"])
        return e

    prs = _ensure_list(_load("gh_pull_requests.json"))
    pr = None
    for p in prs:
        if isinstance(p, dict) and p.get("id") == pull_request_id and p.get("status") != "deleted":
            pr = p
            break
    if pr is None:
        e = _err("NOT_FOUND", "Pull request not found.", pull_request_id=pull_request_id)
        _log_row("error", e["error"]["code"])
        return e

    changed = pr.get("changed_files")
    if changed is None:
        changed = []
    if not isinstance(changed, list):
        changed = []

    start = 0
    if cursor:
        m = re.match(r"^idx_(\d+)_[0-9a-f]{6,}$", cursor)
        if not m:
            e = _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")
            _log_row("error", e["error"]["code"])
            return e
        start = int(m.group(1))
        if start < 0 or start > len(changed):
            start = len(changed)

    page = changed[start:start + limit]
    next_cursor = None
    if start + limit < len(changed):
        next_cursor = f"idx_{start+limit}_" + hashlib.sha1(f"{pull_request_id}|{start+limit}".encode()).hexdigest()[:8]

    _log_row("ok")
    return {
        "files": page,
        "meta": {
            "total": len(changed),
            "limit": limit,
            "has_more": start + limit < len(changed),
            "next_cursor": next_cursor,
        }
    }

def get_pull_request_status(pull_request_id, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_pull_request_status"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_name():
        if os.path.exists(os.path.join(_DB, "gh_request_logs.json")):
            return "gh_request_logs.json"
        if os.path.exists(os.path.join(_DB, "gh_request_log.json")):
            return "gh_request_log.json"
        return "gh_request_logs.json"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_row(status, error_code=None):
        name = _log_name()
        logs = _ensure_list(_load(name))
        row = {
            "id": "ghrl_" + hashlib.sha1(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit():
        name = _log_name()
        logs = _ensure_list(_load(name))
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str):
                dt = _parse_iso(ts)
                if dt and dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log_row("error", rl["error"]["code"])
        return rl

    if not isinstance(pull_request_id, str) or not re.match(r"^ghpr_[0-9A-Z]{18,}$", pull_request_id):
        e = _err("VALIDATION_ERROR", "Invalid pull_request_id.", field="pull_request_id")
        _log_row("error", e["error"]["code"])
        return e

    prs = _ensure_list(_load("gh_pull_requests.json"))
    pr = None
    for p in prs:
        if isinstance(p, dict) and p.get("id") == pull_request_id and p.get("status") != "deleted":
            pr = p
            break
    if pr is None:
        e = _err("NOT_FOUND", "Pull request not found.", pull_request_id=pull_request_id)
        _log_row("error", e["error"]["code"])
        return e

    review_status = pr.get("review_status") or "unknown"
    if review_status not in ("unknown", "clean", "dirty", "blocked", "draft"):
        review_status = "unknown"

    status = {
        "pull_request_id": pull_request_id,
        "state": pr.get("state"),
        "mergeable": pr.get("mergeable"),
        "review_status": review_status,
        "merged_at": pr.get("merged_at"),
        "merge_commit_sha": pr.get("merge_commit_sha"),
    }

    _log_row("ok")
    return {"status": status}

