def create_pull_request(repository_id, title, base_branch, head_branch, body=None, head_repository_full_name=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "create_pull_request"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("gh_request_log.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs.append({
            "id": "ghrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("gh_request_log.json", logs)

    # Validate inputs
    if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid repository_id.", field="repository_id")
    if not isinstance(title, str) or title.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required and must be non-empty.", field="title")
    if not isinstance(base_branch, str) or base_branch.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "base_branch is required and must be non-empty.", field="base_branch")
    if not isinstance(head_branch, str) or head_branch.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "head_branch is required and must be non-empty.", field="head_branch")
    if body is not None and not isinstance(body, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be a string when provided.", field="body")
    if head_repository_full_name is not None:
        if not isinstance(head_repository_full_name, str) or not re.fullmatch(r"[^/\s]+/[^/\s]+", head_repository_full_name):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "head_repository_full_name must be in 'owner/repo' form.", field="head_repository_full_name")

    repos = _load("gh_repositories.json")
    repo = next((r for r in repos if r.get("id") == repository_id), None)
    if not repo:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)
    if repo.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)

    # Determine review_status based on whether base branch exists as an active branch ref; else unknown.
    refs = _load("gh_git_refs.json")
    base_exists = any(
        rr.get("repository_id") == repository_id and rr.get("ref_type") == "branch"
        and rr.get("name") == base_branch and rr.get("status") == "active"
        for rr in refs
    )
    review_status = "unknown" if not base_exists else "unknown"  # still unknown until reviews/mergeability computed

    prs = _load("gh_pull_requests.json")

    # Allocate next number unique within repository
    max_num = 0
    for r in prs:
        if r.get("repository_id") == repository_id and isinstance(r.get("number"), int):
            if r["number"] > max_num:
                max_num = r["number"]
    number = max_num + 1

    # Enforce unique(repository_id, number)
    if any(r.get("repository_id") == repository_id and r.get("number") == number for r in prs):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Pull request number conflict; please retry.", repository_id=repository_id)

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Generate id: ghpr_ + 18+ chars uppercase/digits
    pr_id = "ghpr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")  # digits match [0-9A-Z]{18,}
    row = {
        "id": pr_id,
        "repository_id": repository_id,
        "github_pull_id": None,
        "number": number,
        "title": title,
        "body": body,
        "creator_login": None,
        "base_branch": base_branch,
        "head_branch": head_branch,
        "head_repository_full_name": head_repository_full_name,
        "state": "open",
        "mergeable": None,
        "merged_by_login": None,
        "merged_at": None,
        "merge_commit_sha": None,
        "changed_files": None,
        "review_status": review_status,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # Validate constraints: number > 0, title non-empty, base/head non-empty, review_status allowed
    if row["number"] <= 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "number must be > 0.", field="number")
    if row["review_status"] is not None and row["review_status"] not in ("unknown", "clean", "dirty", "blocked", "draft"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid review_status derived.", field="review_status")

    prs.append(row)
    _save("gh_pull_requests.json", prs)

    _log("ok")
    return {"pull_request": row}

def update_repository(repository_id, description=None, visibility=None, default_branch=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0154000" if __import__("os").path.isdir("./environment_mix/0154000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "update_repository"

    def _log(status_s, credential_id=None, error_code=None):
        logs = _load("gh_request_log.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs.append({
            "id": "ghrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("gh_request_log.json", logs)

    if not isinstance(repository_id, str) or not re.match(r"^ghr_[0-9A-Z]{18,}$", repository_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid repository_id.", field="repository_id")

    if description is not None and not isinstance(description, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")

    if visibility is not None:
        if not isinstance(visibility, str) or visibility not in ("public", "private", "internal"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "visibility must be one of: public, private, internal.", field="visibility")

    if default_branch is not None:
        if not isinstance(default_branch, str) or len(default_branch) < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_branch must be a non-empty string when provided.", field="default_branch")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.", field="status")

    repos = _load("gh_repositories.json")
    idx = None
    for i, r in enumerate(repos):
        if r.get("id") == repository_id:
            idx = i
            break
    if idx is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)

    repo = repos[idx]
    old_status = repo.get("status")

    # Enforce lifecycle transitions
    if status is not None and status != old_status:
        allowed = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set()
        }
        if old_status not in allowed or status not in allowed[old_status]:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition repository status from '{old_status}' to '{status}'.",
                        from_status=old_status, to_status=status)

    # Apply updates (immutable identifiers are not in params, so nothing to block besides types/enums)
    mutated = False
    if description is not None and description != repo.get("description"):
        repo["description"] = description
        mutated = True
    if visibility is not None and visibility != repo.get("visibility"):
        repo["visibility"] = visibility
        mutated = True
    if default_branch is not None and default_branch != repo.get("default_branch"):
        repo["default_branch"] = default_branch
        mutated = True
    if status is not None and status != repo.get("status"):
        repo["status"] = status
        mutated = True

    if not mutated:
        # No success without effect: treat as conflict-free no-op? Spec doesn't say idempotent.
        # Return updated record only if something changed; otherwise surface NOT_FOUND-like? No; repository exists.
        # Use CONFLICT to indicate no fields changed is not an effect.
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "No changes to apply.")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    repo["updated_at"] = now

    # Constraint: unique(full_name) and unique(github_repo_id) unaffected here.
    # Constraint: owner_login/name non-empty; unchanged.
    repos[idx] = repo
    _save("gh_repositories.json", repos)

    _log("ok")
    return {"repository": repo}
